    List<Cell> sorted = alive.stream().sorted(BY_X_THEN_Y).collect(Collectors.toList());

    ArrayNode cells = MAPPER.createArrayNode();
    for (Cell cell : sorted) {
      ArrayNode pair = MAPPER.createArrayNode();
